CREATE TABLE hg_events(id uuid PRIMARY KEY,household_id uuid NOT NULL REFERENCES hg_households(id),camera_id uuid,rule_version_id uuid,source text NOT NULL CHECK(source IN ('LIVE','REPLAY','SIMULATED')),category text NOT NULL CHECK(category IN ('SECURITY','MOVEMENT','EMERGENCY','SYSTEM')),event_type text NOT NULL,severity text NOT NULL CHECK(severity IN ('INFO','WARNING','CRITICAL')),summary text NOT NULL,confidence double precision CHECK(confidence>=0 AND confidence<=1),occurred_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','ACKNOWLEDGED','RESOLVED','FALSE_POSITIVE')),decisions jsonb NOT NULL DEFAULT '{}',evidence jsonb NOT NULL DEFAULT '{}',producer jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,late boolean NOT NULL DEFAULT false,UNIQUE(household_id,id));
CREATE INDEX hg_events_recent ON hg_events(household_id,occurred_at DESC,id DESC);
CREATE TABLE hg_event_receipts(message_id uuid PRIMARY KEY,event_id uuid NOT NULL,household_id uuid NOT NULL,status text NOT NULL,reason_code text,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hg_cooldowns(household_id uuid NOT NULL,camera_id uuid NOT NULL,rule_id uuid NOT NULL,event_type text NOT NULL,cooldown_until timestamptz NOT NULL,last_event_id uuid NOT NULL,grouped_count integer NOT NULL DEFAULT 0,PRIMARY KEY(household_id,camera_id,rule_id,event_type));
CREATE TABLE hg_pending_correlations(event_id uuid PRIMARY KEY,household_id uuid NOT NULL,visual_candidate jsonb NOT NULL,device_id text NOT NULL,expires_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','MATCHED','EXPIRED')));
CREATE TABLE hg_outbox(id uuid PRIMARY KEY,household_id uuid NOT NULL REFERENCES hg_households(id),event_id uuid,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED','UNKNOWN')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_owner text,idempotency_key text UNIQUE NOT NULL,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX hg_outbox_due ON hg_outbox(status,next_attempt_at);
CREATE TABLE hg_audit(id bigserial PRIMARY KEY,household_id uuid NOT NULL,actor_id integer,action text NOT NULL,entity_id text,before_data jsonb,after_data jsonb,request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hg_sse_log(sequence bigserial PRIMARY KEY,household_id uuid NOT NULL,event_name text NOT NULL,entity_id text NOT NULL,minimal_payload jsonb NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours');
CREATE INDEX hg_sse_home_sequence ON hg_sse_log(household_id,sequence);
CREATE TABLE hg_idempotency(household_id uuid NOT NULL,operation text NOT NULL,key text NOT NULL,body_hash text NOT NULL,response jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',PRIMARY KEY(household_id,operation,key));
CREATE TABLE hg_service_health(name text PRIMARY KEY,status text NOT NULL,last_seen timestamptz NOT NULL DEFAULT now(),details jsonb NOT NULL DEFAULT '{}');
